declare function httpCodeToMessage(code: any): any;
declare function errorToMessage(error: any, defaultMsg?: string): string;
declare function errorToStackText(error: any): string;
export declare const exception: {
    errorToStackText: typeof errorToStackText;
    errorToMessage: typeof errorToMessage;
    /**
     * 转换异常code为用户提示信息
     */
    httpCodeToMessage: typeof httpCodeToMessage;
    /**
     * 检查是否有请求异常
     */
    hasError: (error: any) => boolean;
    /**
     * 201 Created: 资源已经存在
     */
    isExists: (error: any) => boolean;
    /**
     * 204 No Content: 资源不存在
     */
    isNoContent: (error: any) => boolean;
    /**
     * 401 Unauthorized: 登录信息已失效
     */
    isUnauthorized: (error: any) => boolean;
    /**
     * 403 Forbidden: 没有资源权限
     */
    isForbidden: (error: any) => boolean;
    /**
     * 404 Not Found: 未找到指定资源
     */
    isNotFound: (error: any) => boolean;
    /**
     * 406 Need Login: 要求登录后访问资源
     */
    isLoginRequired: (error: any) => boolean;
};
export {};
